#!/usr/bin/env python3
"""Widget picker previews for جدولي. Called from patch-android.py after patch_widgets.
Adds previewImage (PNG, all Android versions) and previewLayout (Android 12+, uses the phone's own fonts)
to the four appwidget-provider files so the widget list shows what each widget looks like."""
import base64, os
from patch_widgets import w, NS, info

BG, PANEL, INK, SOFT, ACC = "#FF140B1F", "#FF1F1333", "#FFFFF4EA", "#FFBBA8CC", "#FFFFB547"

PNG = {
    "big": "",
    "small": "",
    "habits": "",
    "hijri": "",
}

def tvx(text, size, color, bold=True, extra=""):
    st = ' android:textStyle="bold"' if bold else ""
    return (f'<TextView android:layout_width="wrap_content" android:layout_height="wrap_content" '
            f'android:textSize="{size}sp" android:textColor="{color}"{st} android:text="{text}"{extra} />')

def bgimg(color, drawable="wd_round18"):
    return (f'<ImageView android:layout_width="match_parent" android:layout_height="match_parent" '
            f'android:scaleType="fitXY" android:src="@drawable/{drawable}" android:tint="{color}" />')

def root(inner):
    return (f'<?xml version="1.0" encoding="utf-8"?>\n<FrameLayout {NS}\n    android:layout_width="match_parent"\n'
            f'    android:layout_height="match_parent">\n{inner}\n</FrameLayout>\n')

def center(inner, pad=10):
    return (f'<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" '
            f'android:orientation="vertical" android:gravity="center" android:padding="{pad}dp">{inner}</LinearLayout>')

ROWS = [("04:58", "الفجر"), ("06:15", "الشروق"), ("11:44", "الظهر"), ("15:12", "العصر"), ("17:51", "المغرب"), ("19:10", "العشاء")]

def big_layout():
    rows = ""
    for i, (t, n) in enumerate(ROWS):
        c = ACC if i == 3 else INK
        rows += ('<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" '
                 'android:orientation="horizontal" android:gravity="center_vertical">'
                 f'<TextView android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:gravity="start" android:textSize="14sp" android:textStyle="bold" android:textColor="{c}" android:text="{t}" />'
                 f'<TextView android:layout_width="0dp" android:layout_height="wrap_content" android:layout_weight="1" android:gravity="end" android:textSize="14sp" android:textStyle="bold" android:textColor="{c}" android:text="{n}" />'
                 '</LinearLayout>')
    inner = (bgimg(BG) +
        '<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="horizontal" '
        'android:layoutDirection="ltr" android:baselineAligned="false" android:padding="10dp">'
        '<LinearLayout android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1" android:orientation="vertical" '
        f'android:paddingStart="6dp" android:paddingEnd="12dp">{rows}</LinearLayout>'
        '<FrameLayout android:layout_width="0dp" android:layout_height="match_parent" android:layout_weight="1">'
        + bgimg(PANEL, "wd_round14") +
        '<LinearLayout android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:gravity="center" android:padding="8dp">'
        + tvx("باقي على العصر", 16, INK, extra=' android:gravity="center"') + tvx("01:30:44", 32, ACC) +
        '</LinearLayout></FrameLayout></LinearLayout>')
    return root(inner)

def small_layout():
    return root(bgimg(BG) + center(tvx("باقي على العصر", 14, INK, extra=' android:gravity="center"') + tvx("01:30:44", 28, ACC)))

def habits_layout():
    bar = "●●●●●●○○○○"
    return root(bgimg(BG) + center(
        tvx("عاداتك النهاردة", 13, SOFT) + tvx("٣ / ٥", 30, ACC) +
        tvx(bar, 14, ACC, bold=False, extra=' android:layout_marginTop="4dp" android:textDirection="ltr"') +
        tvx("فاضل ٢", 12, INK, bold=False, extra=' android:layout_marginTop="6dp"'), 14))

def hijri_layout():
    return root(bgimg(BG) + center(
        tvx("الخميس ١٦ شوال ١٤٤٧", 17, INK, extra=' android:gravity="center"') +
        tvx("الجاية: العصر  15:12", 14, ACC, bold=False, extra=' android:layout_marginTop="4dp" android:gravity="center"'), 12))

def with_preview(xml, key):
    add = (f'\n    android:previewImage="@drawable/wd_prev_{key}"'
           f'\n    android:previewLayout="@layout/widget_{key}_preview"')
    return xml.replace('\n    android:resizeMode', add + '\n    android:resizeMode', 1)

def apply(app, pkg, man):
    rs = f"{app}/res"
    os.makedirs(f"{rs}/drawable-nodpi", exist_ok=True)
    for key, b64 in PNG.items():
        open(f"{rs}/drawable-nodpi/wd_prev_{key}.png", "wb").write(base64.b64decode(b64))
    w(f"{rs}/layout/widget_big_preview.xml", big_layout())
    w(f"{rs}/layout/widget_small_preview.xml", small_layout())
    w(f"{rs}/layout/widget_habits_preview.xml", habits_layout())
    w(f"{rs}/layout/widget_hijri_preview.xml", hijri_layout())
    specs = {"big": (250, 140, "wd_big_desc"), "small": (110, 70, "wd_small_desc"),
             "habits": (110, 110, "wd_habits_desc"), "hijri": (250, 70, "wd_hijri_desc")}
    for key, (mw, mh, desc) in specs.items():
        w(f"{rs}/xml/widget_{key}_info.xml", with_preview(info(mw, mh, f"widget_{key}", desc), key))
    print("widget previews OK")
    return man
